BATCH_ITEMS=[
  {
    "check_id": "W7B8:W7B8:CHK-0125",
    "property_id": "PROP-W5B14-13",
    "title": "Does commitment deduplication in verify_cell_kzg_proof_batch preserve semantic equivalence?",
    "severity": "Critical",
    "bug_class": "Off-by-one / Index Mapping Error",
    "notes": "Off-by-one in commitment_indices could cause weights to aggregate against wrong commitment.",
    "code_excerpt": "// VerifyDataColumnsSidecarKZGProofs (p2p_interface.go):
// For each sidecar and each column:
//   commitments[i] = kzg.Bytes48(sidecar.KzgCommitments[i])  // i-th commitment
//   indices[i] = sidecar.Index  // column index
//   cells[i] = kzg.Cell(sidecar.Column[i])
//   proofs[i] = kzg.Bytes48(sidecar.KzgProofs[i])
// Then: kzg.VerifyCellKZGProofBatch(commitments, indices, cells, proofs)

// c-kzg-4844 C library verify_cell_kzg_proof_batch:
// 1. Validates all input lengths match
// 2. Calls deduplicate_commitments(unique_commitments, commitment_indices, commitments_bytes, num_cells)
//    - commitment_indices[k] = index into unique_commitments for commitments_bytes[k]
//    - unique_commitments is the deduplicated array
// 3. Validates each unique commitment via validate_kzg_g1
// 4. compute_weighted_sum_of_commitments uses commitment_indices to:
//    - For each k: r_powers[k] * unique_commitments[commitment_indices[k]]
//    - This is the key: uses commitment_indices[k] NOT k to look up commitment

// Correctness invariant: commitment_indices[k] = j iff unique_commitments[j] == commitments_bytes[k]
// The deduplication uses byte equality: two commitments are the same iff all 48 bytes match
// This is STRONGER than semantic equivalence (same G1 point): different byte encodings of same point
// are treated as DIFFERENT commitments. But BLS12-381 compressed encoding is unique per G1 point
// (canonical compressed form), so byte equality == semantic equality for valid G1 points.

// The deduplication algorithm in c-kzg-4844 uses a sort+unique pattern:
// 1. Creates array of (commitment_bytes, original_index) pairs
// 2. Sorts by commitment_bytes (byte comparison)
// 3. Assigns sequential unique_commitment indices
// 4. Maps original_index -> unique_commitment_index via commitment_indices array
// This is a standard and correct deduplication algorithm."
  },
  {
    "check_id": "W7B8:W7B8:CHK-0126",
    "property_id": "PROP-W5B14-13",
    "title": "Is the commitment_indices mapping bijective on equivalence classes?",
    "severity": "High",
    "bug_class": "Mapping Bijectivity",
    "code_excerpt": "// Bijectivity analysis of commitment deduplication:
// Forward: commitment_indices[k] uniquely identifies which unique_commitment corresponds to commitments_bytes[k]
//   - This is many-to-one: multiple k values can map to the same unique_commitment index (for duplicate commitments)
// Backward: each value in commitment_indices corresponds to exactly one unique_commitment
//   - The unique_commitments array contains DISTINCT commitment bytes (by construction)
//   - Two different values j1, j2 in unique_commitments always have j1 != j2 bytes

// The mapping is:
//   commitment_indices: N -> M (surjective, not injective for duplicates)
//   unique_commitments: M -> G1 (injective, since unique)
//   Composition: commitments_bytes[k] == unique_commitments[commitment_indices[k]] (for all k)

// Equivalence classes: {k : commitments_bytes[k] == C} for each unique C
// Each equivalence class maps to exactly one index j in unique_commitments
// The weight accumulation sums r_powers[k] for all k in the same equivalence class
// This correctly aggregates all random weights for cells sharing the same commitment

// In compute_weighted_sum_of_commitments:
// For each unique commitment j: sum_k_where_commitment_indices[k]==j (r_powers[k]) * unique_commitments[j]
// This is the correct formulation for batch verification with shared commitments"
  },
  {
    "check_id": "W7B8:W7B8:CHK-0127",
    "property_id": "PROP-W5B14-13",
    "title": "Can a malicious P2P peer exploit commitment deduplication to forge valid proofs?",
    "severity": "Critical",
    "bug_class": "Batch Verification Forgery via Deduplication",
    "code_excerpt": "// Attack scenario: attacker controls commitment bytes in DataColumnSidecar
// Goal: forge a DataColumnSidecar with invalid cells that passes verify_cell_kzg_proof_batch

// Key observations for attack feasibility:
// 1. Each DataColumnSidecar has ONE column index and multiple blobs
//    -> commitments[i] = sidecar.KzgCommitments[i] for each blob i
//    -> all cells in a single sidecar share their commitment by blob (sidecar.KzgCommitments[i])

// 2. Batch verification aggregates across sidecars in verifyKzgBatch:
//    allDataColumns = [] from multiple kzgVerifier items
//    VerifyDataColumnsSidecarKZGProofs(allDataColumns)
//    -> multiple sidecars from different P2P peers can be batched together

// 3. Can attacker mix their malicious sidecar with victim's sidecar to cause verification pass?
//    - In batch mode: r_powers are computed from H(commitment_bytes || cell_data || proof_bytes)
//    - Attacker cannot predict r_powers for other peers' honest commitments
//    - Deduplication: if attacker's commitment happens to collide (byte-identical) with an honest commitment,
//      the weights are aggregated TOGETHER
//    - If honest commitment C appears k1 times, attacker's identical-byte commitment C also appears k2 times,
//      total weight for C = sum(r_powers[k1 items]) + sum(r_powers[k2 items])
//    - The pairing check: e(weighted_sum_proofs, g2_pow_s) == e(weighted_sum_commits - weighted_eval, g2)
//    - For the equation to hold with mixed honest+forged data: attacker needs forged_proof for SAME commitment C
//    - But if attacker submits (C, forged_cell, forged_proof) and C is honest's commitment,
//      then forged_proof would need to be a valid KZG proof for C at the attacker's cell_index,
//      which they cannot forge without discrete log of C's secret

// 4. Deduplication does NOT help the attacker here: mixing identical commitments in a batch
//    does not change the security proof since the randomness (r_powers) is derived from all inputs
//    via hash, and the batch verification equation remains sound under random linear combination"
  },
  {
    "check_id": "W7B8:W7B8:CHK-0128",
    "property_id": "PROP-W5B14-13",
    "title": "What is the impact on validator-node if commitment deduplication fails?",
    "severity": "High",
    "bug_class": "Validator Impact Assessment",
    "code_excerpt": "// Impact of deduplication bug on validator-node:

// If commitment_indices mapping has an off-by-one:
//   - Weight for cell k would be aggregated against wrong commitment C' != commitments_bytes[k]
//   - Pairing check: e(sum r_i * proof_i, g2^s) = e(sum r_i * (commit_i - eval_i), g2)
//   - With wrong commit attribution: e(sum r_i * proof_i) = e(sum r_i * (C'_misattributed - eval_i))
//   - This is NOT a valid KZG equation for any known commitment
//   - Result: pairing check FAILS -> function returns false -> ErrInvalidKZGProof -> ValidationReject
//   - Impact on validator: DoS (valid data rejected, not invalid data accepted)

// If deduplication accepts invalid proof (the goal the attacker wants):
//   - Valid KZG proofs are accepted -> data availability check passes
//   - Validator node would attest to data availability of a blob that is NOT actually available
//   - This could allow an attacker to publish a block header with unavailable data,
//     get it attested to, and potentially cause fork or consensus violation
//   - But: this requires the deduplication to ACCEPT an invalid proof, not just mess up indices
//   - The more likely failure mode (index off-by-one) causes rejection, not acceptance

// Validator impact flow:
//   invalid DataColumnSidecar -> validateDataColumn -> ValidationReject
//   -> peer score penalty -> sidecar not forwarded
//   -> validator node misses DA check for that slot/column
//   -> might affect attestation if validator is custodying that column
//   But: due to custody redundancy (multiple validators per column), one missed sidecar
//   is unlikely to affect consensus unless majority of custodians are targeted"
  }
]

